package dev.oqthara.runtime;

import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Error helpers used by generated bytecode.
 *
 * <p>A compiled program must report the same message, hint, line, column and file as
 * {@code oq run}, because a {@code catch} clause binds the error value and a program may
 * print {@code err.line} or {@code err.file}. Generated code calls {@link #mark} right before
 * every operation that can raise an {@code OqError}, and the runtime helpers used by compiled
 * code read that position through {@link #current} instead of reporting a synthetic one.
 * {@code oq run} marks the same way, in the interpreter's call funnel, so both backends
 * report the same position.
 *
 * <p>The slot is per thread. Compiled code is single-threaded, but the interpreter runs user
 * code on virtual threads for {@code spawn} and {@code par_map}, and two callbacks sharing
 * one slot would report each other's positions (ADR-0025).
 */
public final class Errors {
    private static final Map<String, Span> SPANS = new ConcurrentHashMap<>();

    private static final ThreadLocal<Span> current = ThreadLocal.withInitial(Span::synthetic);

    private Errors() {
    }

    /**
     * Records the source position of the operation that is about to run.
     *
     * <p>The source is cut down to its file name because that is what {@code oq run} reports:
     * the runner parses with {@code file.getFileName()}, and {@code oq build} embeds the same
     * base name for its launcher. A jar built from {@code dir/prog.oq} must therefore say
     * {@code prog.oq}, not {@code dir/prog.oq}.
     */
    public static void mark(String source, Object line, Object column) {
        current.set(span(source, line, column));
    }

    /**
     * Records a position the caller already holds as a {@link Span}.
     *
     * <p>The interpreter evaluates expressions to spans rather than to a source name, a line
     * and a column, so this is how it marks.
     */
    public static void mark(Span span) {
        current.set(span == null ? Span.synthetic() : span);
    }

    /** The position recorded by the last {@link #mark}, or a synthetic span when none was. */
    public static Span current() {
        return current.get();
    }

    /** The span for one source position, interned so a loop does not allocate per step. */
    public static Span span(String source, Object lineValue, Object columnValue) {
        long line = Values.asLong(lineValue);
        long column = Values.asLong(columnValue);
        if (line < 1 || column < 1) return Span.synthetic();
        String name = sourceName(source);
        String key = name + '\u0000' + line + '\u0000' + column;
        return SPANS.computeIfAbsent(key, ignored -> Span.at(name, (int) line, (int) column));
    }

    /** The last path segment of {@code source}, which is the name {@code oq run} reports. */
    public static String sourceName(String source) {
        if (source == null || source.isEmpty()) return "unknown";
        int slash = Math.max(source.lastIndexOf('/'), source.lastIndexOf('\\'));
        return slash < 0 ? source : source.substring(slash + 1);
    }

    /** The {@code error()} builtin: throws an {@code OqError} at the marked position. */
    public static Object raise(Object message) {
        throw new OqError(Values.display(message), current());
    }

    /** The value a {@code catch} clause binds, exactly as the interpreter's {@code toValue}. */
    public static Object catchValue(Object error) {
        return ((OqError) error).toValue();
    }

    /**
     * Turns a JDK refusal to change an unchangeable collection into the program error it is.
     *
     * <p>Both backends share this so a program gets one verdict whichever way it is run: a
     * compiled jar used to report {@code internal error} and exit 70 for a failure the
     * interpreter reported as a program error and exit 1. A tuple keeps its own wording, because
     * the value really is a tuple; anything else is a JDK collection the program built itself,
     * such as {@code List.of(1, 2, 3)}, and blaming Oqthara for that would be wrong.
     */
    public static OqError immutableRefusal(UnsupportedOperationException error, Span span) {
        if (OqTuple.IMMUTABLE.equals(error.getMessage())) {
            return new OqError(OqTuple.IMMUTABLE, span,
                    "Tuples cannot change after they are made. Build a new tuple with the items"
                            + " you want, or use a list when the items must change.");
        }
        String message = error.getMessage();
        return new OqError("cannot change an unchangeable collection: "
                + (message == null || message.isBlank() ? "the operation is not supported" : message),
                span,
                "This value was built unchangeable, for example by List.of(...). Build a list"
                        + " when the items must change.");
    }
}
